using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.ArchitectureTest;

public sealed class LayerDependencyTests
{
    private const string DomainNs = "PaymentAuthorization.Domain";
    private const string ApplicationNs = "PaymentAuthorization.Application";
    private const string InfrastructureNs = "PaymentAuthorization.Infrastructure";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics",
        "Microsoft.Data", "Microsoft.EntityFrameworkCore", "Microsoft.Extensions", "Newtonsoft",
    ];

    private static Types Domain => Types.InAssembly(typeof(Money).Assembly);
    private static Types Application => Types.InAssembly(typeof(AuthorizePayment).Assembly);

    [Fact]
    public void Domain_does_not_depend_on_other_layers()
    {
        var result = Domain.That().ResideInNamespaceStartingWith(DomainNs)
            .ShouldNot().HaveDependencyOnAny(ApplicationNs, InfrastructureNs).GetResult();
        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        var result = Application.That().ResideInNamespaceStartingWith(ApplicationNs)
            .ShouldNot().HaveDependencyOn(InfrastructureNs).GetResult();
        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Domain_and_Application_do_not_use_technical_libraries()
    {
        foreach (var types in new[] { Domain, Application })
        {
            var result = types.ShouldNot().HaveDependencyOnAny(TechnicalNamespaces).GetResult();
            Assert.True(result.IsSuccessful, Describe(result));
        }
    }

    private static string Describe(TestResult result) =>
        "Layer violation in: " + string.Join(", ", result.FailingTypeNames ?? []);
}
